package com.denfense.server.service;
import com.denfense.server.domain.BattleSettlement; import com.denfense.server.repository.BattleSettlementRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class BattleSettlementLookup { private final BattleSettlementRepository repository; @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRES_NEW,readOnly=true) public BattleSettlement byRequest(String id){return repository.findByRequestId(id).orElse(null);} @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRES_NEW,readOnly=true) public BattleSettlement bySession(String id){return repository.findByBattleSessionId(id).orElse(null);} }
